class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_i = events[0][0]
        best_t = events[0][1]
        for j in range(1, len(events)):
            t = events[j][1] - events[j - 1][1]
            if t > best_t or (t == best_t and events[j][0] < best_i):
                best_t = t
                best_i = events[j][0]
        return best_i

